def prod_signs(arr):
    if not arr:
        return None
    abs_sum = sum(abs(x) for x in arr)
    sign_prod = 1
    for x in arr:
        sign_prod *= -1 if x < 0 else (1 if x > 0 else 0)
    return sign_prod * abs_sum
